from __future__ import annotations

from collections.abc import Callable
from typing import Any

import streamlit as st

from optichub.grpc_client import ModuleInfo, configure_module, start_module, stop_module


def tab_prefect_worker(
    host: str,
    port: int,
    info: ModuleInfo | None,
    cfg: dict[str, Any],
    running: bool,
    can_stop: bool,
    key: Callable[[str], str],
) -> None:
    work_pool = st.text_input(
        "Work pool",
        value=str(cfg.get("work_pool", "default")),
        key=key("m_pw_pool"),
    )
    worker_count = st.number_input(
        "Worker count",
        min_value=1,
        max_value=64,
        value=int(cfg.get("worker_count", 1)),
        step=1,
        key=key("m_pw_count"),
    )
    extra = cfg.get("extra_args") or []
    extra_text = "\n".join(str(x) for x in extra) if isinstance(extra, list) else ""
    extra_lines = st.text_area(
        "Extra CLI args (one per line)",
        value=extra_text,
        height=80,
        key=key("m_pw_extra"),
    )
    extra_args = [ln.strip() for ln in extra_lines.splitlines() if ln.strip()]

    payload = {
        "work_pool": work_pool.strip() or "default",
        "worker_count": int(worker_count),
        "extra_args": extra_args,
    }

    c1, c2 = st.columns(2)
    with c1:
        if st.button("Start", type="primary", disabled=running, key=key("m_pw_start")):
            ok, msg = start_module(host, port, module="prefect_worker", config=payload)
            if ok:
                st.success(msg or "started")
                st.rerun()
            else:
                st.error(msg)
    with c2:
        if st.button("Stop", disabled=not can_stop, key=key("m_pw_stop")):
            ok, msg = stop_module(host, port, module="prefect_worker")
            if ok:
                st.success(msg or "stopped")
                st.rerun()
            else:
                st.error(msg)

    if st.button("Apply config (restart module)", disabled=not running, key=key("m_pw_apply")):
        ok, msg = configure_module(host, port, module="prefect_worker", config=payload)
        if ok:
            st.success(msg or "reconfigured")
            st.rerun()
        else:
            st.error(msg)


def tab_lsm_process_server(
    host: str,
    port: int,
    info: ModuleInfo | None,
    cfg: dict[str, Any],
    running: bool,
    can_stop: bool,
    key: Callable[[str], str],
) -> None:
    _serve_modes = ("all", "process", "archive")
    _mode = str(cfg.get("serve_mode", "all"))
    serve_mode = st.selectbox(
        "Serve mode",
        options=list(_serve_modes),
        index=_serve_modes.index(_mode) if _mode in _serve_modes else 0,
        key=key("m_lps_mode"),
    )
    concurrent_workers = st.number_input(
        "Concurrent workers",
        min_value=1,
        max_value=64,
        value=int(cfg.get("concurrent_workers", 2)),
        step=1,
        key=key("m_lps_cw"),
    )
    extra = cfg.get("extra_args") or []
    extra_text = "\n".join(str(x) for x in extra) if isinstance(extra, list) else ""
    extra_lines = st.text_area(
        "Extra CLI args (one per line)",
        value=extra_text,
        height=80,
        key=key("m_lps_extra"),
    )
    extra_args = [ln.strip() for ln in extra_lines.splitlines() if ln.strip()]

    payload = {
        "serve_mode": serve_mode,
        "concurrent_workers": int(concurrent_workers),
        "extra_args": extra_args,
    }

    c1, c2 = st.columns(2)
    with c1:
        if st.button("Start", type="primary", disabled=running, key=key("m_lps_start")):
            ok, msg = start_module(host, port, module="lsm_process_server", config=payload)
            if ok:
                st.success(msg or "started")
                st.rerun()
            else:
                st.error(msg)
    with c2:
        if st.button("Stop", disabled=not can_stop, key=key("m_lps_stop")):
            ok, msg = stop_module(host, port, module="lsm_process_server")
            if ok:
                st.success(msg or "stopped")
                st.rerun()
            else:
                st.error(msg)

    if st.button("Apply config (restart module)", disabled=not running, key=key("m_lps_apply")):
        ok, msg = configure_module(host, port, module="lsm_process_server", config=payload)
        if ok:
            st.success(msg or "reconfigured")
            st.rerun()
        else:
            st.error(msg)


def tab_oct_process_server(
    host: str,
    port: int,
    info: ModuleInfo | None,
    cfg: dict[str, Any],
    running: bool,
    can_stop: bool,
    key: Callable[[str], str],
) -> None:
    project_name = st.text_input(
        "Project name (required)",
        value=str(cfg.get("project_name", "")),
        key=key("m_ops_pn"),
    )
    deployment_name = st.text_input(
        "Deployment name",
        value=str(cfg.get("deployment_name", "local")),
        key=key("m_ops_dn"),
    )
    concurrency_limit = st.number_input(
        "Concurrency limit",
        min_value=1,
        max_value=64,
        value=int(cfg.get("concurrency_limit", 1)),
        step=1,
        key=key("m_ops_cl"),
    )
    exclude = cfg.get("exclude") or []
    exclude_text = "\n".join(str(x) for x in exclude) if isinstance(exclude, list) else ""
    exclude_lines = st.text_area(
        "Exclude flows (one per line)",
        value=exclude_text,
        height=80,
        key=key("m_ops_exclude"),
    )
    exclude_list = [ln.strip() for ln in exclude_lines.splitlines() if ln.strip()]

    extra = cfg.get("extra_args") or []
    extra_text = "\n".join(str(x) for x in extra) if isinstance(extra, list) else ""
    extra_lines = st.text_area(
        "Extra CLI args (one per line)",
        value=extra_text,
        height=80,
        key=key("m_ops_extra"),
    )
    extra_args = [ln.strip() for ln in extra_lines.splitlines() if ln.strip()]

    payload = {
        "project_name": project_name.strip(),
        "deployment_name": deployment_name.strip() or "local",
        "concurrency_limit": int(concurrency_limit),
        "exclude": exclude_list,
        "extra_args": extra_args,
    }

    c1, c2 = st.columns(2)
    with c1:
        if st.button("Start", type="primary", disabled=running, key=key("m_ops_start")):
            ok, msg = start_module(host, port, module="oct_process_server", config=payload)
            if ok:
                st.success(msg or "started")
                st.rerun()
            else:
                st.error(msg)
    with c2:
        if st.button("Stop", disabled=not can_stop, key=key("m_ops_stop")):
            ok, msg = stop_module(host, port, module="oct_process_server")
            if ok:
                st.success(msg or "stopped")
                st.rerun()
            else:
                st.error(msg)

    if st.button("Apply config (restart module)", disabled=not running, key=key("m_ops_apply")):
        ok, msg = configure_module(host, port, module="oct_process_server", config=payload)
        if ok:
            st.success(msg or "reconfigured")
            st.rerun()
        else:
            st.error(msg)
